(()=>{const original=new WeakMap();const attrs=new WeakMap();const keys=Object.keys(SGEnglish).sort((a,b)=>b.length-a.length);let queued=false;const isEn=()=>localStorage.getItem('sg-lang')==='"en"';function trans(s){for(const k of keys)s=s.split(k).join(SGEnglish[k]);return s}function run(){queued=false;const en=isEn();document.querySelectorAll('.language-note').forEach(n=>{if(en)n.hidden=true});const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(n.parentElement.closest('script,style'))continue;let r=original.get(n);if(!r||n.nodeValue!==r.last){r={text:n.nodeValue,last:n.nodeValue};original.set(n,r)}if(n.parentElement.tagName==='OPTION'&&!n.parentElement.hasAttribute('value'))n.parentElement.value=r.text;const v=en?trans(r.text):r.text;if(n.nodeValue!==v)n.nodeValue=v;r.last=v}document.querySelectorAll('[placeholder],[aria-label],[title],[alt]').forEach(el=>{let a=attrs.get(el)||{};for(const k of ['placeholder','aria-label','title','alt'])if(el.hasAttribute(k)){let r=a[k];const cur=el.getAttribute(k);if(!r||cur!==r.last)r={text:cur,last:cur};const v=en?trans(r.text):r.text;if(cur!==v)el.setAttribute(k,v);r.last=v;a[k]=r}attrs.set(el,a)});const guide=document.querySelector('a[href="./stockholm-free.html"],a[href="./stockholm-free-en.html"]');if(guide)guide.href=en?'./stockholm-free-en.html':'./stockholm-free.html';document.title=en?'Sweden Travel Guide | Stockholm Guide':'Sweden Travel Guide | Stockholm Guide'}new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(run)}}).observe(document.body,{childList:true,subtree:true,characterData:true});document.addEventListener('change',()=>queueMicrotask(run));run()})();